"""
Module to define the determination os  the syslog log files for the keyword "Get Log File".
"""
import tarfile
import os
import pathlib
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ClassicalGnbSyslogLogfileProvider:
    """Concrete implementation to determine the location of the packed syslog archive, unzip its log files and
    provide the list of all included log files as returned value.
    """

    def get_syslog_log_file(self, log_directory, collector_config):
        """Function to provide the log files based on the network_element and target_dir. The correct
        collector is determined in the collector configuration to get the path where the log file was storred
        by "collect collectors". Knowing the resulting filename, this tgz file is taken to unpack the containing
        syslogs and return the full paths to those log files.

        :param str log_directory: the path where the log files of the collector are stored
        :param str collector_config: the collector configuration of the collector to obtain additional information
        """
        tgz_path_file = os.path.join(log_directory, "syslog_files.tgz")
        logger.info(f"Tgz File Path: {tgz_path_file}")

        tgz_path_dir = os.path.join(log_directory, "syslog_files")

        if tarfile.is_tarfile(tgz_path_file) is True:
            with tarfile.open(tgz_path_file, 'r:gz', ) as my_tgz_file:
                if not os.path.exists(tgz_path_dir):
                    os.makedirs(tgz_path_dir)
                logger.info(f"Extract tgz file: {tgz_path_file} to {tgz_path_dir}")
                my_tgz_file.extractall(path=tgz_path_dir)

                return [
                    os.path.join(tgz_path_dir, tgz_rel_path)
                    for tgz_rel_path in [
                        os.path.join(tgz_path_dir, str(pathlib.Path(tgz_path_name)))
                        for tgz_path_name in my_tgz_file.getnames()
                        if os.path.basename(tgz_path_name) != '']
                    if os.path.isfile(os.path.join(tgz_path_dir, tgz_rel_path))]

        else:
            raise AssertionError(f"File is not a valid tar archive: {tgz_path_file}")
